	result, err := JSONLBytes(input)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	var _ RedactedBytes = result
	if !bytes.Equal(result.Bytes(), input) {
		t.Errorf("expected unchanged content, got %q", result.Bytes())
	}
}
```

2. Implement `RedactedBytes` type, `Bytes()` method, and `AlreadyRedacted` constructor. Add to `redact/redact.go` after the `const RedactedPlaceholder = "REDACTED"` line:

```go
// RedactedBytes represents transcript data that has been through secret
// redaction. Consumers that require pre-redacted input (e.g., compact.Compact,
// checkpoint stores) accept this type to enforce the contract at compile time.
//
// Produced by JSONLBytes (primary constructor) or AlreadyRedacted (escape hatch).
type RedactedBytes []byte

// Bytes returns the underlying byte slice.
func (r RedactedBytes) Bytes() []byte {
	return []byte(r)
}

// AlreadyRedacted wraps data that is known to have been redacted by a prior
// operation. Use this ONLY for trusted sources — e.g., transcripts read back
// from storage (which were redacted on write) or synthetic test data.
// This is NOT a way to bypass redaction for fresh transcripts.
func AlreadyRedacted(data []byte) RedactedBytes {
	return RedactedBytes(data)
}
```

3. Update `JSONLBytes` to return `RedactedBytes` instead of `([]byte, error)`:

```go
// JSONLBytes redacts secrets in JSONL-formatted byte content and returns
// the result as RedactedBytes, certifying the output has been through redaction.
func JSONLBytes(b []byte) (RedactedBytes, error) {
	s := string(b)
	redacted, err := JSONLContent(s)
	if err != nil {
		return nil, err
	}
	if redacted == s {
		return RedactedBytes(b), nil
	}
	return RedactedBytes(redacted), nil
}
```

4. Fix existing `JSONLBytes` tests that compare with `[]byte`. Update `TestJSONLBytes_NoSecrets` — the pointer comparison `&result[0] != &input[0]` no longer works since the return type changed:

```go
func TestJSONLBytes_NoSecrets(t *testing.T) {
	input := []byte(`{"type":"text","content":"hello"}`)
	result, err := JSONLBytes(input)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if string(result.Bytes()) != string(input) {
		t.Errorf("expected unchanged input, got %q", result.Bytes())
	}
}
```

Update `TestJSONLBytes_WithSecret`:

```go
func TestJSONLBytes_WithSecret(t *testing.T) {
	input := []byte(`{"type":"text","content":"key=` + highEntropySecret + `"}`)
	result, err := JSONLBytes(input)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	expected := []byte(`{"type":"text","content":"REDACTED"}`)
	if !bytes.Equal(result.Bytes(), expected) {
		t.Errorf("got %q, want %q", result.Bytes(), expected)
	}
}
```

5. Run all redact tests: `go test ./redact/ -v` — all must PASS.
6. Do NOT commit yet — just implement and verify tests pass. The build will break for other packages that depend on the old JSONLBytes signature; that's expected and will be fixed in subsequent tasks.

## Context

This is the foundation for the entire refactor. The `RedactedBytes` type will be consumed by `compact.Compact` (Task 2), `WriteCommittedOptions.Transcript` (Task 3), and various callers. The type creates a compile-time contract that data has been through secret redaction before being passed to downstream consumers.

